Algorithm Propina
  Define cuenta As Integer;
  Define amigos As Integer;
  Read cuenta;
  Read amigos;
  If amigos = 0 Then
    Write "No hay quien pague";
  Else
    Write "Cada uno paga: ", ceil((cuenta + cuenta Div 10) / amigos);
  EndIf
EndAlgorithm

