Subroutine TotalConPropina(cuenta As Integer) As Integer
  Return cuenta + cuenta Div 10;
EndSubroutine

Subroutine ParteDeCadaUno(total As Integer, amigos As Integer) As Integer
  Return ceil(total / amigos);
EndSubroutine

